CREATE TABLE homepage_content(id text PRIMARY KEY NOT NULL,payload text NOT NULL CHECK(json_valid(payload)),version integer NOT NULL DEFAULT 1,updated_by text REFERENCES users(id),updated text NOT NULL);
--> statement-breakpoint
CREATE TABLE homepage_assets(id text PRIMARY KEY NOT NULL,name text NOT NULL,mime text NOT NULL,size integer NOT NULL,user_id text NOT NULL REFERENCES users(id),created text NOT NULL);
--> statement-breakpoint
CREATE TABLE homepage_revisions(id text PRIMARY KEY NOT NULL,user_id text NOT NULL REFERENCES users(id),version integer NOT NULL UNIQUE,payload text NOT NULL CHECK(json_valid(payload)),created text NOT NULL);
--> statement-breakpoint
INSERT INTO homepage_content(id,payload,version,updated) VALUES('main','{"heroTitle":"Selamat Datang di","heroTagline":"BERSAMA MEMBANGUN SUMATERA SELATAN","heroIntro":"Mari bersama-sama bergabung dalam program Tanggung Jawab Sosial dan Lingkungan (TJSL) untuk berkontribusi bagi pembangunan dan kesejahteraan masyarakat di Provinsi Sumatera Selatan.","about":"Aplikasi Siaptanjak adalah sebuah platform digital yang dirancang untuk memfasilitasi manajemen perusahaan dalam melaporkan kegiatan TJSL nya agar lebih mudah, efektif dan transparan.","whatsapp":"6285822222262","email":"pramtramtamtam@gmail.com","logo":"/logo.png","provinceLogo":"/visual/pemprov-sumsel.png","goals":[{"title":"Efisiensi Pelaporan","description":"Mempermudah perusahaan dalam menyusun, merencanakan, melacak, melaporkan dan mengevaluasi kegiatan TJSL secara mudah, efisien, sistematis, profesional dan aman."},{"title":"Transparan","description":"Menyediakan akses informasi yang jelas bagi pemangku kepentingan terkait pelaksanaan program TJSL, sehingga membangun kepercayaan publik."},{"title":"Mendukung Tujuan Pembangunan Berkelanjutan (SDGs)","description":"Mendorong pelaksanaan program TJSL yang selaras dengan tujuan pembangunan berkelanjutan."},{"title":"Membangun Kolaborasi dan Sinergi menjadi Lebih Baik","description":"Memfasilitasi sinergi antara perusahaan, pemerintah, dan masyarakat dalam pelaksanaan kegiatan TJSL."}],"activities":[{"theme":"Infrastruktur","title":"Pembangunan transportasi dan sarana olahraga","intro":"","photos":[["/visual/kegiatan/mini-trans.png","Pembangunan Stasiun Mini Trans","PT Bukit Asam Tbk"],["/visual/kegiatan/bowling-pertamina.png","Sarana olahraga bowling","Pertamina"],["/visual/kegiatan/olahraga-bowling.png","Pemanfaatan sarana olahraga","Dokumentasi kegiatan"],["/visual/kegiatan/olahraga-bukit-asam.png","Dukungan kegiatan sepak bola","PT Bukit Asam Tbk"]]},{"theme":"Sosial dan Pengentasan Kemiskinan","title":"Rumah layak, kehidupan lebih baik","intro":"Contoh dukungan perbaikan rumah dan bantuan sosial untuk masyarakat.","photos":[["/visual/kegiatan/bedah-rumah.png","Program bedah rumah dan GEBRAK","Bukit Asam, Bank Sumsel Babel, KAI, dan mitra lainnya"],["/visual/kegiatan/bpr-sumsel.png","Penyaluran bantuan TJSL","Bank BPR Sumsel"]]},{"theme":"Pengendalian Inflasi","title":"Kolaborasi menjaga kebutuhan masyarakat","intro":"Contoh operasi pasar murah untuk mendukung ketersediaan bahan pokok dan stabilitas harga.","photos":[["/visual/kegiatan/pasar-murah.png","Operasi Pasar Murah Provinsi Sumatera Selatan","Kolaborasi pemangku kepentingan"],["/visual/kegiatan/pasar-sumsel-energi.png","Operasi Pasar Murah KM 5","PT Sumsel Energi Gemilang"]]},{"theme":"Usaha Ekonomi Kerakyatan","title":"Menguatkan usaha dan kemandirian pangan","intro":"Contoh dukungan Sumsel Mandiri Pangan dan pemberdayaan pembudidaya ikan.","photos":[["/visual/kegiatan/gsm-bank-sumsel.png","Gerakan Sumsel Mandiri Pangan","Bank Sumsel Babel"],["/visual/kegiatan/gsm-mandiri.png","Dukungan Sumatera Selatan Mandiri Pangan","Bank Mandiri"],["/visual/kegiatan/perikanan-pertamina.png","Pemberdayaan pembudidaya ikan","Kilang Pertamina Plaju"]]},{"theme":"Pendidikan dan Kesehatan","title":"Investasi untuk generasi yang lebih sehat","intro":"Dokumentasi pendidikan dan pelayanan kesehatan di Sumatera Selatan.","photos":[["/visual/kegiatan/beasiswa.jpg","Program beasiswa studi kedokteran","Dokumentasi pendidikan"],["/visual/kegiatan/sekolah.jpg","Peresmian sarana pendidikan","Dokumentasi pendidikan"],["/visual/kegiatan/layanan-kesehatan.jpg","Kunjungan pelayanan kesehatan masyarakat","Dokumentasi kesehatan"],["/visual/kegiatan/kunjungan-kesehatan.jpg","Dukungan pelayanan kesehatan","Dokumentasi kesehatan"]]},{"theme":"Lingkungan Hidup dan Kedaruratan Bencana","title":"Lingkungan terjaga, masyarakat tangguh","intro":"Dokumentasi koordinasi dan penanganan kebakaran hutan dan lahan (karhutla).","photos":[["/visual/kegiatan/koordinasi-bencana.jpg","Koordinasi penanggulangan bencana","Dokumentasi koordinasi"],["/visual/kegiatan/rapat-karhutla.jpg","Rapat koordinasi penanggulangan karhutla","Dokumentasi koordinasi"],["/visual/kegiatan/relawan-karhutla.jpg","Dukungan relawan karhutla","Dokumentasi lapangan"],["/visual/kegiatan/tinjauan-karhutla.jpg","Peninjauan lokasi karhutla","Dokumentasi lapangan"]]}],"laws":[{"name":"UU No. 40 Tahun 2007","title":"Perseroan Terbatas","description":"Pasal 74: kewajiban TJSL bagi perseroan yang menjalankan kegiatan usaha di bidang atau berkaitan dengan sumber daya alam.","file":"/dokumen/uu-40-2007.pdf","source":"https://peraturan.go.id/id/uu-no-40-tahun-2007","extra":"","pages":140},{"name":"PP No. 47 Tahun 2012","title":"Tanggung Jawab Sosial dan Lingkungan Perseroan Terbatas","description":"Pelaksanaan Pasal 74 UU Perseroan Terbatas, termasuk rencana kerja tahunan, anggaran, pelaksanaan, dan laporan TJSL.","file":"/dokumen/pp-47-2012.pdf","source":"https://peraturan.go.id/id/pp-no-47-tahun-2012","extra":"/dokumen/pp-47-2012-penjelasan.pdf","pages":4},{"name":"UU No. 25 Tahun 2007","title":"Penanaman Modal","description":"Pasal 15, 16, dan 34: kewajiban tanggung jawab sosial perusahaan, tanggung jawab penanam modal, dan sanksi administratif.","file":"/dokumen/uu-25-2007.pdf","source":"https://peraturan.go.id/id/uu-no-25-tahun-2007","extra":"","pages":43},{"name":"Permen BUMN No. PER-1/MBU/03/2023","title":"Penugasan Khusus dan Program Tanggung Jawab Sosial dan Lingkungan Badan Usaha Milik Negara","description":"Mengatur penugasan khusus dan penyelenggaraan program TJSL BUMN, termasuk perencanaan, pelaksanaan, serta pelaporan.","file":"/dokumen/permen-bumn-1-2023.pdf","source":"https://peraturan.go.id/id/permen-bumn-no-per-1-mbu-03-2023-tahun-2023","extra":"","pages":17},{"name":"UU No. 22 Tahun 2001","title":"Minyak dan Gas Bumi","description":"Pasal 11 dan 40: pengembangan masyarakat sekitar serta tanggung jawab terhadap lingkungan dan masyarakat dalam kegiatan usaha migas.","file":"/dokumen/uu-22-2001.pdf","source":"https://peraturan.go.id/id/uu-no-22-tahun-2001","extra":"","pages":53},{"name":"PP No. 93 Tahun 2010","title":"Sumbangan Penanggulangan Bencana Nasional, Sumbangan Penelitian dan Pengembangan, Sumbangan Fasilitas Pendidikan, Sumbangan Pembinaan Olahraga, dan Biaya Pembangunan Infrastruktur Sosial yang Dapat Dikurangkan dari Penghasilan Bruto","description":"Mengatur jenis sumbangan dan biaya tertentu yang dapat dikurangkan dari penghasilan bruto dengan memenuhi persyaratan yang ditetapkan.","file":"/dokumen/pp-93-2010.pdf","source":"https://peraturan.go.id/id/pp-no-93-tahun-2010","extra":"/dokumen/pp-93-2010-penjelasan.pdf","pages":5},{"name":"SK Gubernur Sumatera Selatan No. 409/KPTS/BAPPEDA/2026","title":"Pembentukan Tim Koordinasi Forum Tanggung Jawab Sosial dan Lingkungan Provinsi Sumatera Selatan Tahun 2026–2031","description":"Keputusan Gubernur tanggal 2 Juli 2026 tentang susunan dan koordinasi Forum TJSL Provinsi Sumatera Selatan.","file":"/dokumen/sk-csr-2026.pdf","source":"","extra":"","pages":10}]}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
